import json
import pickle
from contextlib import asynccontextmanager
from typing import List

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

MODEL = None
MODEL_NAME = None
MODEL_TYPE = None


@asynccontextmanager
async def lifespan(app):
    global MODEL, MODEL_NAME, MODEL_TYPE
    with open('/app/models/best_model.pkl', 'rb') as f:
        MODEL = pickle.load(f)
    try:
        with open('/app/output/model_comparison.json') as f:
            MODEL_NAME = json.load(f)['best_model_name']
    except Exception:
        MODEL_NAME = type(MODEL).__name__
    MODEL_TYPE = type(MODEL).__name__
    yield


app = FastAPI(title='California Housing Price API', lifespan=lifespan)


class PredictRequest(BaseModel):
    features: List[float] = Field(..., min_length=8, max_length=8)


class BatchRequest(BaseModel):
    features_list: List[List[float]]


@app.post('/predict')
def predict(req: PredictRequest):
    pred = MODEL.predict([req.features])
    return {'prediction': float(pred[0]), 'model_name': MODEL_NAME}


@app.get('/health')
def health():
    return {'status': 'healthy', 'model_loaded': MODEL is not None}


@app.get('/model-info')
def model_info():
    return {'model_name': MODEL_NAME, 'model_type': MODEL_TYPE, 'features_count': 8}


@app.post('/predict-batch')
def predict_batch(req: BatchRequest):
    for row in req.features_list:
        if len(row) != 8:
            raise HTTPException(status_code=422, detail='Each inner array must have exactly 8 features')
    if len(req.features_list) == 0:
        return {'predictions': [], 'model_name': MODEL_NAME, 'count': 0}
    preds = MODEL.predict(req.features_list)
    return {
        'predictions': [float(p) for p in preds],
        'model_name': MODEL_NAME,
        'count': len(preds),
    }
EOF
